<?php
/** READ ONLY inspection of canonical portal tasks in the disposable native HTTP database. */
if(PHP_SAPI!=='cli'||getenv('ISSUERS_BROWSER_DB_NAME')!=='argws_upgrade_ci')exit(2);
set_exception_handler(static function($e){fwrite(STDERR,get_class($e).':'.$e->getMessage().PHP_EOL);exit(1);});
define('FCPATH',dirname(__DIR__,2).'/');define('BASEPATH',FCPATH.'system/');define('APPPATH',FCPATH.'application/');require FCPATH.'application/config/app-config.php';
if(APP_DB_NAME!=='argws_upgrade_ci'||!preg_match('/^(127\.0\.0\.1|argws-crm-provision-db-[0-9]+)(:[0-9]+)?$/D',APP_DB_HOSTNAME))exit(2);
$pdo=new PDO('mysql:host='.str_replace(':',';port=',APP_DB_HOSTNAME).';dbname='.APP_DB_NAME.';charset=utf8mb4',APP_DB_USERNAME,APP_DB_PASSWORD,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);$pdo->exec('SET SESSION TRANSACTION READ ONLY');$pdo->beginTransaction();register_shutdown_function(static function()use($pdo){if($pdo->inTransaction())$pdo->rollBack();});
$config=[];require FCPATH.'application/config/migration.php';$target=$config['migration_version']??null;$marker=(int)$pdo->query('SELECT version FROM tblmigrations')->fetchColumn();if(!is_int($target)||$target<450||$marker!==$target)throw new RuntimeException('Exact native450 or later required');
$owners=[];foreach(['a'=>'11222333000181','b'=>'52998224725']as$letter=>$tax){$s=$pdo->prepare('SELECT id FROM tblissuers_registry WHERE tax_id=?');$s->execute([$tax]);$owners[$letter]=(int)$s->fetchColumn();}if(min($owners)<1)throw new RuntimeException('Existing native A/B owners required');
