$mode=$argv[1]??'inspect';
if($mode==='inspect'){$tasks=[];foreach($owners as$owner){$q=$pdo->prepare('SELECT t.id,t.project_id,t.issuer_id,t.assignee_id,t.due_date FROM tblcompany_tasks t JOIN tblcompany_portal_task_origins o ON o.issuer_id=t.issuer_id AND o.project_id=t.project_id AND o.task_id=t.id WHERE t.issuer_id=? AND t.assignee_id=0 AND t.due_date=? ORDER BY t.id');$q->execute([$owner,'2026-11-01']);$rows=$q->fetchAll(PDO::FETCH_ASSOC);if(!$rows)throw new RuntimeException('Canonical prior portal writer0 dueNov1 required; this fixture never seeds it');foreach($rows as&$r){foreach(['id','project_id','issuer_id','assignee_id']as$k)$r[$k]=(int)$r[$k];}unset($r);$tasks[$owner]=$rows;}echo json_encode(['read_only'=>true,'native_marker'=>$marker,'owners'=>$owners,'tasks'=>$tasks],JSON_THROW_ON_ERROR);exit;}
if($mode==='snapshot'){$r=[];foreach($pdo->query('SHOW TABLES')->fetchAll(PDO::FETCH_COLUMN)as$table){if(!preg_match('/^tbl[A-Za-z0-9_]+$/D',$table))throw new RuntimeException('Unexpected table');if(preg_match('/^tbl(?:options|invoices|invoicepaymentrecords|creditnotes|credits|creditnote_refunds|issuers_registry|issuers_invoice_documents|company_(?:payment_|credit_|financial_|expense|local_noncash|invoice_|task|standalone|project_requests|portal_task)|asaas_|bb_)/D',$table))$r[$table]=calendarPortalHash($pdo->query('SELECT * FROM `'.$table.'`')->fetchAll(PDO::FETCH_ASSOC));}ksort($r);echo json_encode($r,JSON_THROW_ON_ERROR);exit;}exit(2);
